import {hash} from '../store.mjs';
export const normalizeCell=x=>String(x).replace(/<[^>]*>/g,' ').replace(/&(?:nbsp|amp|lt|gt|quot|apos);|&#(?:x[0-9a-f]+|\d+);/gi,e=>{const named={'&nbsp;':' ','&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'"};return named[e.toLowerCase()]??String.fromCodePoint(e[2].toLowerCase()==='x'?parseInt(e.slice(3,-1),16):parseInt(e.slice(2,-1),10));}).replace(/\s+/g,' ').trim();
export function htmlTableProofs(bytes){return [...bytes.toString('utf8').matchAll(/<table\b[^>]*>[\s\S]*?<\/table>/gi)].map((m,index)=>{const rows=[...m[0].matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].map(r=>[...r[1].matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(c=>normalizeCell(c[1]))).filter(r=>r.length);return {index,rawHash:hash(m[0]),matrixDigest:hash(JSON.stringify(rows))};});}
export function bindRawTable(t,proofs){const matrixDigest=hash(JSON.stringify(t.rows.map(r=>r.cells.map(normalizeCell)))),proof=proofs.find(p=>p.matrixDigest===matrixDigest);if(!proof)throw Object.assign(Error('원가 표 구조·수치가 저장 원문 HTML과 일치하지 않습니다.'),{status:409});return {...t,rawTableProof:proof};}
